+      validateLedger({
+        ...baseLedger,
+        expenses: [
+          {
+            payer: 'Alice',
+            amountMinor: 1200,
+            description: 'Snacks',
+            participants: ['Alice', 'Casey'],
+            split: 'equal',
+          },
+        ],
+      }),
+    /Expense at index 0 has unknown participant: Casey\./,
+  );
